1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import net.officefloor.plugin.variable.Out;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
9	import org.springframework.web.bind.annotation.RequestBody;
10	
11	/**
12	 * Rejects a create request that is missing or blank in any required owner field, before
13	 * {@link BuildOwner} runs. Binds the body without {@code @Valid} so the missing fields are
14	 * reported as an {@code errors} array (via {@link MissingOwnerFieldsException}) rather than as
15	 * bean-validation schema errors. This is the only step that binds the body; it republishes it
16	 * for {@link BuildOwner} to consume.
17	 */
18	public class ValidateOwnerRequiredFields {
19	
20	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
21	            throws MissingOwnerFieldsException {
22	        List<String> missing = new ArrayList<>();
23	        if (isBlank(request.getFirstName())) {
24	            missing.add("firstName");
25	        }
26	        if (isBlank(request.getLastName())) {
27	            missing.add("lastName");
28	        }
29	        if (isBlank(request.getAddress())) {
30	            missing.add("address");
31	        }
32	        if (isBlank(request.getCity())) {
33	            missing.add("city");
34	        }
35	        if (isBlank(request.getTelephone())) {
36	            missing.add("telephone");
37	        }
38	        if (!missing.isEmpty()) {
39	            throw new MissingOwnerFieldsException(missing);
40	        }
41	        validated.set(request);
42	    }
43	
44	    private static boolean isBlank(String value) {
45	        return value == null || value.isBlank();
46	    }
47	}
