7	/**
8	 * Normalizes the telephone on create into E.164 form (see {@link E164Telephone}). Mutates the
9	 * validated {@link OwnerFieldsDto} in place so {@link BuildOwner} maps the stored E.164 value, and
10	 * rejects anything that cannot form a valid number with 400 via {@link InvalidTelephoneException}.
11	 */
12	public class NormalizeOwnerTelephone {
13	
14	    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
15	        request.setTelephone(E164Telephone.toE164(request.getTelephone()));
16	    }
