3	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
4	
5	/**
6	 * Converts a raw telephone into E.164 form. Spaces, dashes and brackets are stripped. A leading
7	 * '+' with its country code is kept; otherwise country code '+61' is assumed and a single leading
8	 * '0' is dropped from the national digits. The result must carry 8 to 15 digits after the '+',
9	 * else it is rejected with {@link InvalidTelephoneException} (a 400). So {@code '0412 345 678'}
10	 * becomes {@code '+61412345678'} and {@code '+64 21 123 456'} becomes {@code '+6421123456'}.
11	 */
12	final class E164Telephone {
13	
14	    private E164Telephone() {
15	    }
16	
17	    /** Normalize to E.164, throwing when the value cannot form a valid number. */
18	    static String toE164(String raw) throws InvalidTelephoneException {
19	        String cleaned = raw == null ? "" : raw.replaceAll("[\\s()\\-]", "");
20	        String digits;
21	        if (cleaned.startsWith("+")) {
22	            digits = cleaned.substring(1);
23	        }
24	        else {
25	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
26	            digits = "61" + national;
27	        }
28	        if (!digits.matches("\\d{8,15}")) {
29	            throw new InvalidTelephoneException(raw);
30	        }
31	        return "+" + digits;
32	    }
33	
34	    /** Normalize to E.164, or {@code null} when the value cannot form a valid number. */
35	    static String toE164OrNull(String raw) {
36	        try {
37	            return toE164(raw);
38	        }
39	        catch (InvalidTelephoneException ex) {
40	            return null;
41	        }
42	    }
43	}
