3	import java.util.List;
4	import java.util.Objects;
5	
6	import net.officefloor.plugin.section.clazz.Parameter;
7	import net.officefloor.web.ObjectResponse;
8	import org.springframework.http.HttpStatus;
9	import org.springframework.http.ProblemDetail;
10	import org.springframework.http.ResponseEntity;
11	import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
12	import org.springframework.validation.BindingResult;
13	import org.springframework.web.bind.MethodArgumentNotValidException;
14	
15	public class ValidationExceptionHandler {
16	
17	    public void handle(@Parameter MethodArgumentNotValidException ex,
18	            ObjectResponse<ResponseEntity<ProblemDetail>> response) {
19	        ProblemDetail detail = ProblemDetails.build(ex, HttpStatus.BAD_REQUEST,
20	                "The request contains invalid or missing parameters");
21	        BindingResult bindingResult = ex.getBindingResult();
22	        if (bindingResult.hasErrors()) {
23	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
24	                    .map(fieldError -> {
25	                        String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
26	                        String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
27	                        String message = "Field '%s' %s (rejected value: %s)".formatted(
28	                                fieldError.getField(), defaultMessage, rejectedValue);
29	                        return new ValidationMessageDto(message)
30	                                .putAdditionalProperty("field", fieldError.getField())
31	                                .putAdditionalProperty("rejectedValue", rejectedValue)
32	                                .putAdditionalProperty("defaultMessage", defaultMessage);
33	                    })
34	                    .toList();
35	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
36	        }
37	        response.send(ResponseEntity.status(HttpStatus.BAD_REQUEST).body(detail));
38	    }
39	}
